50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
54	const ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
58	
59	/** What the MHPCO knows about a kind of item it will insure: what insuring
60	 *  one costs (`basePremium`), and what one is insured FOR (`insuranceValue`,
61	 *  from which the cap is derived — never from premiums). One entry per kind,
62	 *  so the two figures for a kind cannot drift apart. */
63	interface ItemKind {
64	  basePremium: number;
65	  insuranceValue: number;
66	}
67	
68	/** The MHPCO's price list. */
69	const ITEM_KINDS: Record<string, ItemKind> = {
70	  sword: { basePremium: 100, insuranceValue: 1000 },
71	  amulet: { basePremium: 60, insuranceValue: 600 },
72	  staff: { basePremium: 80, insuranceValue: 800 },
73	  potion: { basePremium: 40, insuranceValue: 400 },
74	  rune: { basePremium: 25, insuranceValue: 250 },
75	  moonstone: { basePremium: 25, insuranceValue: 250 },
76	};
77	
78	const basePremiumOfType = (type: string): number =>
79	  ITEM_KINDS[type].basePremium;
80	
81	const insuranceValueOfType = (type: string): number =>
82	  ITEM_KINDS[type].insuranceValue;
83	
84	const DEDUCTIBLE_PER_DAMAGED_ITEM = 100;
85	const CAP_MULTIPLE = 2;
86	
87	/** The enchantment level from which a CLAIM is only half reimbursed. A claim
88	 *  rule, unrelated to ENCHANTMENT_SURCHARGE_LEVEL, which gates a premium
89	 *  surcharge — the two thresholds differ and move independently. */
90	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
91	const HALF_REIMBURSEMENT_PERCENT = 50;
92	
93	/** Modifiers are expressed as an amount to add, never as a factor to multiply
94	 *  by, so that they stay additive against their base and so that the integer
95	 *  numerator keeps float artifacts out of the final rounding
96	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
97	const percentOf = (amount: number, percent: number): number =>
98	  (amount * percent) / 100;
99	
100	/** Rounds up — premiums round in the MHPCO's favour. */
101	const roundPremium = (amount: number): number => Math.ceil(amount);
102	
103	/** Rounds down — payouts, too, round in the MHPCO's favour. */
104	const roundPayout = (amount: number): number => Math.floor(amount);
105	
106	const COMPONENT_BLOCK_SIZE = 3;
107	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
108	
109	const COMPONENT_TYPES = ["rune", "moonstone"];
110	
111	const isComponent = (item: Item): boolean =>
112	  COMPONENT_TYPES.includes(item.type);
113	
114	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
115	
116	const countByType = (items: Item[]): Map<string, number> => {
117	  const counts = new Map<string, number>();
118	  for (const item of items) {
119	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
120	  }
121	  return counts;
122	};
123	
124	/** A block is exactly three alike components, priced as a unit rather than
125	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
126	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
127	  count === COMPONENT_BLOCK_SIZE
128	    ? COMPONENT_BLOCK_BASE_PREMIUM
129	    : count * basePremiumOfType(type);
130	
131	const sum = (amounts: number[]): number =>
132	  amounts.reduce((total, amount) => total + amount, 0);
133	
134	const policyBasePremium = (items: Item[]): number => {
135	  const mainItems = items.filter((item) => !isComponent(item));
136	  const componentGroups = [...countByType(items.filter(isComponent))];
137	
138	  return (
139	    sum(mainItems.map(itemBasePremium)) +
140	    sum(componentGroups.map(componentGroupBasePremium))
141	  );
142	};
143	
144	interface ItemModifierRule {
145	  appliesTo: (item: Item) => boolean;
146	  percent: number;
147	}
148	
149	/** Every item-scoped modifier, as a rule that either applies to an item or
150	 *  does not. Applicable rules stack. */
151	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
152	  {
153	    appliesTo: (item) => item.cursed === true,
154	    percent: CURSE_SURCHARGE_PERCENT,
155	  },
156	  {
157	    appliesTo: (item) => (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL,
158	    percent: ENCHANTMENT_SURCHARGE_PERCENT,
159	  },
160	];
161	
162	/** Item-scoped modifiers apply to the affected item's own base premium,
163	 *  not to the policy total. */
164	const itemModifierAmount = (item: Item): number =>
165	  sum(
166	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
167	      percentOf(itemBasePremium(item), rule.percent),
168	    ),
169	  );
170	
171	/** A policy written by a quote step, as later claim steps see it. The insured
172	 *  items are kept because a damage entry names only a type, while the clauses
173	 *  that govern its reimbursement depend on the insured item itself. */
174	interface Policy {
175	  remainingCap: number;
176	  items: Item[];
177	}
178	
179	/** What a step leaves behind for the steps after it. Steps are not
180	 *  independent: a quote is priced against how many contracts precede it, and
181	 *  a claim is paid against a policy an earlier quote wrote, so running a
182	 *  scenario threads this state from each step to the next. */
183	interface ScenarioState {
184	  customer: Customer;
185	  precedingContracts: number;
186	  /** Keyed by the zero-based index of the quote step that wrote the policy —
187	   *  which is what a claim step's `policy` field refers to. */
188	  policiesByStep: Record<number, Policy>;
189	}
190	
191	const initialState = (customer: Customer): ScenarioState => ({
192	  customer,
193	  precedingContracts: 0,
194	  policiesByStep: {},
195	});
196	
197	/** A step's outcome: what it reports, and the state the next step sees. */
198	interface StepOutcome {
199	  result: StepResult;
200	  state: ScenarioState;
201	}
202	
203	/** What a policy-wide rule may look at: the customer, plus where this quote
204	 *  sits in the customer's history of contracts. A pricing view of the
205	 *  scenario state — rules read it, they never advance it. */
206	type PolicyContext = Readonly<ScenarioState>;
207	
208	interface PolicyModifierRule {
209	  appliesTo: (context: PolicyContext) => boolean;
210	  /** Signed: positive surcharges, negative discounts. */
211	  percent: number;
212	}
213	
214	/** Every policy-wide modifier, as a rule that either applies to a policy or
215	 *  does not. Applicable rules stack. */
216	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
217	  {
218	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
219	    percent: -LOYALTY_DISCOUNT_PERCENT,
220	  },
221	  {
222	    appliesTo: () => true,
223	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
224	  },
225	  {
226	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
227	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
228	  },
229	];
230	
231	/** Policy-wide modifiers apply to the policy base premium — the sum of every
232	 *  item's base premium — not to any single item. */
233	const policyModifierAmount = (
234	  basePremium: number,
235	  context: PolicyContext,
236	): number =>
237	  sum(
238	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
239	      (rule) => percentOf(basePremium, rule.percent),
240	    ),
241	  );
242	
243	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
244	  const basePremium = policyBasePremium(items);
245	  // Every modifier is an amount added to the base premium, not a factor
246	  // compounded onto a running total: item-scoped modifiers take a percentage
247	  // of their own item's base premium, policy-wide ones take a percentage of
248	  // the policy base premium.
249	  const modifierAmounts = [
250	    ...items.map(itemModifierAmount),
251	    policyModifierAmount(basePremium, context),
252	  ];
253	  // The processing fee is added last, after all percentage modifiers.
254	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
255	  return { premium: roundPremium(premium) };
256	};
257	
258	/** The cap on everything a policy will ever pay out: twice the sum of the
259	 *  insured items' values. Premium modifiers do not raise it. */
260	const policyCap = (items: Item[]): number =>
261	  CAP_MULTIPLE * sum(items.map((item) => insuranceValueOfType(item.type)));
262	
263	/** What one damage entry reimburses before the deductible: the full damage,
264	 *  unless a special clause reduces it. */
265	const reimbursableAmount = (damage: Damage, insuredItem: Item): number =>
266	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
267	    ? percentOf(damage.amount, HALF_REIMBURSEMENT_PERCENT)
268	    : damage.amount;
269	
270	/** The insured item a damage entry refers to. A damage entry names only a
271	 *  type, while the clauses governing its reimbursement depend on the item.
272	 *  The cast is the one place this lookup is assumed to succeed: a damage
273	 *  entry for an item outside the policy is an error case that is not yet
274	 *  implemented, and this is where it will be handled. */
275	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
276	  policy.items.find((item) => item.type === damage.itemType) as Item;
277	
278	/** What one damage entry pays out: the reimbursable amount, less the
279	 *  deductible that is charged once per damaged item. */
280	const damagePayout = (damage: Damage, policy: Policy): number =>
281	  reimbursableAmount(damage, insuredItemFor(damage, policy)) -
282	  DEDUCTIBLE_PER_DAMAGED_ITEM;
283	
284	/** The state that results from recording one policy against a step index,
285	 *  replacing any policy already recorded there. */
286	const withPolicy = (
287	  state: ScenarioState,
288	  stepIndex: number,
289	  policy: Policy,
290	): ScenarioState => ({
291	  ...state,
292	  policiesByStep: { ...state.policiesByStep, [stepIndex]: policy },
293	});
294	
295	/** Writes a policy, and records it so later claim steps can be paid against
296	 *  it. Each quote written also becomes a preceding contract for the next. */
297	const runQuote = (
298	  step: QuoteStep,
299	  stepIndex: number,
300	  state: ScenarioState,
301	): StepOutcome => ({
302	  result: quote(step.items, state),
303	  state: withPolicy(
304	    { ...state, precedingContracts: state.precedingContracts + 1 },
305	    stepIndex,
306	    { remainingCap: policyCap(step.items), items: step.items },
307	  ),
308	});
309	
310	/** What an incident claims in total, before the policy's cap is applied:
311	 *  every damage entry reimbursed on its own terms, less its own deductible. */
312	const claimedAmount = (damages: Damage[], policy: Policy): number =>
313	  sum(damages.map((damage) => damagePayout(damage, policy)));
314	
315	/** A policy never pays out more than the cap it has left, so a claim that
316	 *  exhausts the cap is paid down to it rather than past it. */
317	const paidWithinCap = (claimed: number, remainingCap: number): number =>
318	  Math.min(claimed, remainingCap);
319	
320	/** Pays a claim against the policy an earlier quote step wrote, drawing the
321	 *  payout down from that policy's remaining cap. */
322	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
323	  const policy = state.policiesByStep[step.policy];
324	  const payout = roundPayout(
325	    paidWithinCap(
326	      claimedAmount(step.incident.damages, policy),
327	      policy.remainingCap,
328	    ),
329	  );
330	  const remainingCap = policy.remainingCap - payout;
331	  return {
332	    result: { payout, remainingCap },
333	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
334	  };
335	};
336	
337	const runStep = (
338	  step: Step,
339	  stepIndex: number,
340	  state: ScenarioState,
341	): StepOutcome =>
342	  step.op === "quote"
343	    ? runQuote(step, stepIndex, state)
344	    : runClaim(step, state);
345	
346	export const runScenario = (scenario: Scenario): ScenarioResult => {
347	  const { results } = scenario.steps.reduce(
348	    ({ results, state }, step, stepIndex) => {
349	      const outcome = runStep(step, stepIndex, state);
350	      return { results: [...results, outcome.result], state: outcome.state };
351	    },
352	    { results: [] as StepResult[], state: initialState(scenario.customer) },
353	  );
354	  return { results };
355	};
